// main.cpp -- ESP32 firmware for the UTME Weeble drone.
// Flight logic lives in weeble_core.h; every physical number comes from weeble_config.h (generated by build.py).
//
// TWO WAYS TO SEND COMMANDS (both work at the same time, same commands):
//   1. USB cable: PlatformIO Serial Monitor at 115200 baud.
//   2. WiFi: the drone makes its own network (name/password below). Join it from the laptop, then run
//      weeble_remote.py (recommended: it sends a heartbeat) or connect PuTTY "Raw" to 192.168.4.1 port 23.
//
// Commands (end with Enter):
//   status                 state + estimator readout
//   unlock / lock          safety lock (boots locked)
//   cal                    at-rest calibration: drone still and upright (or at its resting tilt), takes 2 s
//   arm / disarm           arm needs: unlocked + calibrated
//   cap <percent>          throttle cap (boots at 15 %). 'cap 100' for real flights
//   hop [feet] [bearing]   powered hop, default 5 ft straight ahead (bearing = degrees clockwise)
//   ascent [metres]        straight up, hover, land (max ASCENT_MAX_HEIGHT_M)
//   descent [metres]       arm the drop routine (release height, default 6.096 m)
//   servo <x_deg> <y_deg>  bench: tilt the motor stack (disarmed only, motors stay off)
//   spin <percent> <secs>  bench: run both motors and stream RPM + accel (armed, no routine) -- props off or tethered!
//   pose / posesolve / poseclear   six-position accelerometer calibration (hold still in each pose, type 'pose')
//   tele                   toggle 10 Hz telemetry stream
//   k  (or a bare 'k')     KILL: motors off immediately
//   hb                     heartbeat (sent automatically by weeble_remote.py; you never type it)
//
// WiFi safety rule ("link lost"):
//   If the last command came over WiFi and the laptop disappears for LINK_TIMEOUT_MS, the drone:
//     - stops a 'spin' test and the servo bench,
//     - DISARMS if it is armed but sitting idle (no routine running).
//   It does NOT stop a hop / ascent / descent that is already running: those finish and land by themselves,
//   and cutting motors mid-air would turn a WiFi glitch into a crash.
#include <Arduino.h>
#include <Wire.h>
#include <WiFi.h>
#include <Preferences.h>
#include "weeble_core.h"
#include "weeble_muscles.h"

using namespace weeble;

// ============================ WiFi settings (change the password!) ============================
static const char* WIFI_NAME = "weeble";             // network name the laptop joins
static const char* WIFI_PASSWORD = "weeble-1234";    // at least 8 characters
static const uint16_t WIFI_PORT = 23;                // the laptop connects to 192.168.4.1 : 23
static const uint32_t LINK_TIMEOUT_MS = 2000;        // laptop silent this long = link lost

// ============================ Hardware pins ============================
static const uint8_t PIN_ESC_UPPER = 25, PIN_TACH_UPPER = 4,  CH_ESC_UPPER = 0;
static const uint8_t PIN_ESC_LOWER = 26, PIN_TACH_LOWER = 16, CH_ESC_LOWER = 1;
static const uint8_t PIN_SERVO_X   = 27, CH_SERVO_X = 2;
static const uint8_t PIN_SERVO_Y   = 33, CH_SERVO_Y = 3;
static const int     PIN_SDA = 21, PIN_SCL = 22;
static const uint8_t MPU_ADDR = 0x68;

static Params P;
static Flight flight(P);
static Preferences prefs;
static AccelCal acal;

// ESC + tach closed-loop RPM. Motor KV / battery / max RPM / pulse rate come from the config.
static EscController escUpper({PIN_ESC_UPPER, PIN_TACH_UPPER, 2, CH_ESC_UPPER, cfg::MOTOR_KV, cfg::BATTERY_V, cfg::MAX_RPM,
                               (uint16_t)cfg::ESC_PWM_HZ, 1000, 2000, 0.00005f, 0.00005f, 0.000001f, 50.0f, 5, 200});
static EscController escLower({PIN_ESC_LOWER, PIN_TACH_LOWER, 2, CH_ESC_LOWER, cfg::MOTOR_KV, cfg::BATTERY_V, cfg::MAX_RPM,
                               (uint16_t)cfg::ESC_PWM_HZ, 1000, 2000, 0.00005f, 0.00005f, 0.000001f, 50.0f, 5, 200});
static LedcServo srvX(PIN_SERVO_X, 500.0f, 2500.0f, PI, CH_SERVO_X);
static LedcServo srvY(PIN_SERVO_Y, 500.0f, 2500.0f, PI, CH_SERVO_Y);

static bool softLocked = true, teleOn = false;
static uint32_t lastTickUs = 0, teleCount = 0;
static int imuFail = 0;

// bench modes
static bool benchServo = false; static float benchTx = 0, benchTy = 0;
static bool spinOn = false; static float spinFrac = 0; static uint32_t spinEndMs = 0;

// six-position accel calibration samples (chip frame)
static Vec3 poses[12]; static int nPoses = 0;

// ============================ WiFi link state ============================
static WiFiServer server(WIFI_PORT);
static WiFiClient client;                 // the one connected laptop (newest connection wins)
static uint32_t lastHeardMs = 0;          // last time ANY byte arrived from the laptop
static bool heartbeatMode = false;        // true once the laptop sends 'hb' (weeble_remote.py does)
static bool wifiInCharge = false;         // last command came over WiFi -> the link-lost rule applies

// Is the laptop link healthy? With heartbeats: we must have heard from it recently.
// Without (e.g. PuTTY): we can only tell when the connection itself closes.
static bool clientHealthy() {
  if (!client || !client.connected()) return false;
  return !heartbeatMode || (millis() - lastHeardMs < LINK_TIMEOUT_MS);
}

// "out" prints to BOTH the USB serial monitor and the WiFi laptop. Every message in this file uses it.
// (If the laptop has gone quiet we stop sending to it, so a full network buffer can never stall the loop.)
class DualOut : public Print {
 public:
  size_t write(uint8_t c) override { return write(&c, 1); }
  size_t write(const uint8_t* buf, size_t n) override {
    Serial.write(buf, n);
    if (clientHealthy()) client.write(buf, n);
    return n;
  }
};
static DualOut out;

static void safeOutputs() {
  escUpper.stop(); escLower.stop();
  srvX.setAngle(P.servo_center_rad); srvY.setAngle(P.servo_center_rad);
}
static void killAll(const char* why) {
  spinOn = false; benchServo = false; safeOutputs(); flight.kill(why);
  out.print("KILL: "); out.println(why);
}

// ============================ MPU6050 ============================
static void mpuWrite(uint8_t reg, uint8_t val) {
  Wire.beginTransmission(MPU_ADDR); Wire.write(reg); Wire.write(val); Wire.endTransmission();
}
static uint8_t mpuReadReg(uint8_t reg) {
  Wire.beginTransmission(MPU_ADDR); Wire.write(reg);
  if (Wire.endTransmission(false) != 0 || Wire.requestFrom((int)MPU_ADDR, 1) != 1) return 0xFF;
  return Wire.read();
}
// Every chip setting is written explicitly (the very old code left the chip at its power-on defaults).
static bool mpuInit() {
  mpuWrite(0x6B, 0x80); delay(100);                       // reset
  mpuWrite(0x6B, 0x01); delay(10);                        // wake, clock = gyro X PLL
  mpuWrite(0x19, 0x00);                                   // sample rate divider: 1 kHz (with DLPF on)
  mpuWrite(0x1A, cfg::IMU_DLPF_CFG);                      // digital low-pass filter
  mpuWrite(0x1B, (uint8_t)(cfg::IMU_GYRO_FS_SEL << 3));   // gyro range
  mpuWrite(0x1C, (uint8_t)(cfg::IMU_ACCEL_FS_SEL << 3));  // accel range
  delay(50);
  uint8_t who = mpuReadReg(0x75);
  bool ok = (mpuReadReg(0x1B) == (uint8_t)(cfg::IMU_GYRO_FS_SEL << 3)) && (mpuReadReg(0x1C) == (uint8_t)(cfg::IMU_ACCEL_FS_SEL << 3));
  out.printf("MPU WHO_AM_I=0x%02X, ranges %s\n", who, ok ? "set OK" : "NOT set (check wiring!)");
  return ok;
}
// raw chip-frame reading in SI units (calibration applied in the chip frame)
static bool mpuReadChip(Vec3& g, Vec3& a) {
  Wire.beginTransmission(MPU_ADDR); Wire.write(0x3B);
  if (Wire.endTransmission(false) != 0 || Wire.requestFrom((int)MPU_ADDR, 14) != 14) return false;
  uint8_t b[14]; for (int i = 0; i < 14; i++) b[i] = Wire.read();
  float av[3], gv[3];
  for (int i = 0; i < 3; i++) {
    av[i] = (int16_t)((b[i * 2] << 8) | b[i * 2 + 1]) / cfg::IMU_ACCEL_LSB_PER_G * kG;
    gv[i] = (int16_t)((b[8 + i * 2] << 8) | b[8 + i * 2 + 1]) / cfg::IMU_GYRO_LSB_PER_DPS * kDeg2Rad;
  }
  applyAccelCal(acal, av);
  a = Vec3{av[0], av[1], av[2]}; g = Vec3{gv[0], gv[1], gv[2]};
  return true;
}
// body-frame reading (axis mapping from drone_config.py IMU_AXES)
static bool mpuRead(Vec3& g, Vec3& a) {
  Vec3 gc, ac; if (!mpuReadChip(gc, ac)) return false;
  g = imuToBody(gc); a = imuToBody(ac); return true;
}

// average N samples at ~500 Hz; returns false if the drone moved
static bool averageStill(int n, Vec3& gm, Vec3& am, bool chipFrame) {
  Vec3 sg, sa; float sg2 = 0, sa2 = 0; int k = 0;
  for (int i = 0; i < n; i++) {
    Vec3 g, a; bool ok = chipFrame ? mpuReadChip(g, a) : mpuRead(g, a);
    if (ok) { sg = sg + g; sa = sa + a; sg2 += dot(g, g); sa2 += dot(a, a); k++; }
    delay(2);
  }
  if (k < n / 2) return false;
  gm = sg * (1.0f / k); am = sa * (1.0f / k);
  float gstd = sqrtf(fmaxf(sg2 / k - dot(gm, gm), 0.0f)), astd = sqrtf(fmaxf(sa2 / k - dot(am, am), 0.0f));
  out.printf("  gyro std %.4f rad/s, accel std %.3f m/s^2\n", gstd, astd);
  return gstd < 0.02f && astd < 0.15f && norm(gm) < 0.1f;   // not rotating (a rocking weeble would fail here)
}

// ============================ Commands ============================
static void printStatus() {
  const Estimator& e = flight.est;
  out.printf("State=%s routine=%s sub=%s cal=%d lock=%d cap=%.0f%% wifi=%s\n", macroName(flight.macro()), routineName(flight.routine),
             flight.subStateName(), (int)flight.calibrated, (int)softLocked, P.throttle_cap * 100.0f,
             clientHealthy() ? (heartbeatMode ? "connected+heartbeat" : "connected") : "none");
  out.printf("  tilt %.1f deg (lean x %.1f y %.1f), pos (%.2f %.2f %.2f) m, vel (%.2f %.2f %.2f) m/s, thrust %.1f N (k %.2f)\n",
             e.tiltDeg(), e.leanXDeg(), e.leanYDeg(), e.pos.x, e.pos.y, e.pos.z, e.vel.x, e.vel.y, e.vel.z, e.thrustNow(), e.thrust_k);
  if (flight.summary_ready) out.printf("  last mission: %s, touchdown %.2f m/s, tilt %.1f deg, peak %.1f g\n",
                                       flight.end_reason, flight.td_vz, flight.td_tilt, flight.peak_f / kG);
}

static void handleLine(char* line) {
  char* t[8]; int nt = 0;
  for (char* p = strtok(line, " \t"); p && nt < 8; p = strtok(NULL, " \t")) t[nt++] = p;
  if (nt == 0) return;
  const char* cmd = t[0]; const char* a1 = nt > 1 ? t[1] : nullptr; const char* a2 = nt > 2 ? t[2] : nullptr;
  const char* why = "";

  if (!strcmp(cmd, "hb")) { heartbeatMode = true; return; }      // laptop heartbeat: nothing to print
  if (!strcmp(cmd, "status")) printStatus();
  else if (!strcmp(cmd, "unlock")) { softLocked = false; out.println("unlocked"); }
  else if (!strcmp(cmd, "lock")) { softLocked = true; spinOn = false; if (flight.idleArmed()) flight.disarm(); out.println("locked"); }
  else if (!strcmp(cmd, "k")) killAll("key");
  else if (!strcmp(cmd, "tele")) { teleOn = !teleOn; out.println(teleOn ? "telemetry on" : "telemetry off"); }
  else if (!strcmp(cmd, "cal")) {
    if (flight.macro() != Macro::REST) { out.println("refused: disarm first"); return; }
    out.println("calibrating -- keep the drone completely still...");
    Vec3 gm, am;
    if (!averageStill(1000, gm, am, false)) { out.println("cal FAILED: drone moved or is rocking. Wait until still and retry."); return; }
    flight.est.initAtRest(am); flight.est.setGyroBias(gm); flight.calibrated = true;
    out.printf("cal OK: tilt %.2f deg, |a| %.3f m/s^2, gyro bias (%.4f %.4f %.4f) rad/s\n", flight.est.tiltDeg(), norm(am), gm.x, gm.y, gm.z);
  }
  else if (!strcmp(cmd, "arm")) {
    if (softLocked) { out.println("refused: locked"); return; }
    if (flight.arm(why)) { escUpper.arm(0); escLower.arm(0); out.println("ARMED"); } else out.println(why);
  }
  else if (!strcmp(cmd, "disarm")) { spinOn = false; safeOutputs(); flight.disarm(); out.println("disarmed"); }
  else if (!strcmp(cmd, "cap") && a1) { P.throttle_cap = clampf((float)atof(a1) / 100.0f, 0.0f, 1.0f); out.printf("cap %.0f%%\n", P.throttle_cap * 100); }
  else if (!strcmp(cmd, "hop")) {
    float dist = a1 ? (float)atof(a1) * 0.3048f : cfg::HOP_DISTANCE_M, bearing = a2 ? (float)atof(a2) : 0.0f;
    out.println(flight.startHop(dist, bearing, why) ? "HOP STARTED" : why);
  }
  else if (!strcmp(cmd, "ascent")) {
    float h = a1 ? (float)atof(a1) : cfg::ASCENT_HEIGHT_M;
    out.println(flight.startAscent(h, why) ? "ASCENT STARTED" : why);
  }
  else if (!strcmp(cmd, "descent")) {
    float h = a1 ? (float)atof(a1) : cfg::DESCENT_RELEASE_HEIGHT_M;
    out.println(flight.startDescent(h, why) ? "DESCENT ARMED -- waiting for release" : why);
  }
  else if (!strcmp(cmd, "servo")) {
    if (flight.macro() != Macro::REST || softLocked) { out.println("refused: needs unlocked + disarmed"); return; }
    benchServo = a1 != nullptr; benchTx = a1 ? (float)atof(a1) : 0; benchTy = a2 ? (float)atof(a2) : 0;
    if (!benchServo) { safeOutputs(); out.println("servo bench off"); return; }
    Command c; c.tilt_x_deg = benchTx; c.tilt_y_deg = benchTy; Outputs o = mix(c, P);
    srvX.setAngle(o.servo_x_rad); srvY.setAngle(o.servo_y_rad);
    out.printf("pod tilt (%.1f, %.1f) deg -> servo shafts (%.1f, %.1f) deg\n", benchTx, benchTy, o.servo_x_rad * kRad2Deg, o.servo_y_rad * kRad2Deg);
  }
  else if (!strcmp(cmd, "spin")) {
    if (!flight.idleArmed() || softLocked) { out.println("refused: needs unlocked + armed with no routine"); return; }
    float pct = a1 ? (float)atof(a1) : 0, secs = a2 ? (float)atof(a2) : 2.0f;
    spinFrac = clampf(pct / 100.0f, 0.0f, P.throttle_cap); spinEndMs = millis() + (uint32_t)(clampf(secs, 0.1f, 20.0f) * 1000);
    spinOn = spinFrac > 0;
    out.printf("spin %.0f%% (capped) for %.1f s -- columns: ms, rpm_upper, rpm_lower, accel_z\n", spinFrac * 100, secs);
  }
  else if (!strcmp(cmd, "pose")) {
    if (flight.macro() != Macro::REST || nPoses >= 12) { out.println("refused"); return; }
    Vec3 gm, am; if (!averageStill(500, gm, am, true)) { out.println("pose rejected: moved"); return; }
    poses[nPoses++] = am; out.printf("pose %d: (%.2f %.2f %.2f)\n", nPoses, am.x, am.y, am.z);
  }
  else if (!strcmp(cmd, "poseclear")) { nPoses = 0; out.println("poses cleared"); }
  else if (!strcmp(cmd, "posesolve")) {
    AccelCal c; acal.valid = false;               // fit on uncalibrated data
    if (!solveAccelCal(poses, nPoses, c, why)) { out.print("accel cal failed: "); out.println(why); return; }
    acal = c; prefs.begin("weeble", false); prefs.putBytes("acal", &acal, sizeof(acal)); prefs.end();
    out.printf("accel cal saved: rms %.3f m/s^2. Run 'cal' again.\n", acal.rms); flight.calibrated = false;
  }
  else out.println("unknown command");
}

// One character at a time, from either source. Each source has its own line buffer so a half-typed
// USB line and a WiFi line can never mix.
static void feedChar(char ch, char* buf, int& n, bool fromWifi) {
  if (ch == '\r' || ch == '\n') {
    if (n > 0) {
      buf[n] = 0; n = 0;
      if (strcmp(buf, "hb") != 0) wifiInCharge = fromWifi;   // who is "driving" the drone right now
      handleLine(buf);
    }
  }
  else if (n == 0 && (ch == 'k' || ch == 'K')) killAll(fromWifi ? "key (wifi)" : "key");
  else if (n < 63) buf[n++] = ch;
}

static void handleSerial() {
  static char buf[64]; static int n = 0;
  while (Serial.available()) feedChar((char)Serial.read(), buf, n, false);
}

static char wifiBuf[64]; static int wifiN = 0;
static void handleWifi() {
  if (server.hasClient()) {                                  // a laptop is connecting
    WiFiClient fresh = server.accept();
    if (client && client.connected()) client.stop();         // one laptop at a time: newest wins
    client = fresh; client.setNoDelay(true);
    wifiN = 0; heartbeatMode = false; lastHeardMs = millis();
    out.println("laptop connected over WiFi. Type 'status'.");
  }
  while (client && client.available()) { lastHeardMs = millis(); feedChar((char)client.read(), wifiBuf, wifiN, true); }
}

// The link-lost rule (see the top of this file). Runs 20 times a second.
static void linkFailsafe() {
  if (!wifiInCharge) return;                                 // being driven over USB: rule does not apply
  bool lost = (WiFi.softAPgetStationNum() == 0) || !client || !client.connected() ||
              (heartbeatMode && millis() - lastHeardMs > LINK_TIMEOUT_MS);
  if (!lost || millis() - lastHeardMs < LINK_TIMEOUT_MS) return;   // give it LINK_TIMEOUT_MS before acting
  if (spinOn) { spinOn = false; escUpper.stop(); escLower.stop(); out.println("LINK LOST: spin test stopped"); }
  if (benchServo) { benchServo = false; safeOutputs(); out.println("LINK LOST: servo bench off"); }
  if (flight.idleArmed()) { safeOutputs(); flight.disarm(); out.println("LINK LOST: disarmed"); }
  // a hop / ascent / descent that is already running is left alone on purpose
}

// ============================ setup / loop ============================
void setup() {
  Serial.begin(115200); delay(300);
  Wire.begin(PIN_SDA, PIN_SCL); Wire.setClock(400000);
  mpuInit();
  escUpper.begin(); escLower.begin();
  srvX.begin(); srvY.begin();
  safeOutputs();
  prefs.begin("weeble", true);
  if (prefs.getBytes("acal", &acal, sizeof(acal)) == sizeof(acal) && acal.valid) out.println("accel cal loaded");
  prefs.end();

  WiFi.mode(WIFI_AP);
  WiFi.setSleep(false);                                      // lower latency
  if (WiFi.softAP(WIFI_NAME, WIFI_PASSWORD)) {
    server.begin(); server.setNoDelay(true);
    out.printf("WiFi network '%s' up. Laptop: join it, then connect to ", WIFI_NAME);
    out.print(WiFi.softAPIP()); out.printf(" port %u\n", (unsigned)WIFI_PORT);
  } else {
    out.println("WiFi FAILED to start (password must be 8+ characters). USB serial still works.");
  }

  out.printf("Weeble ready. config 0x%08X, mass %.0f g, thrust %.1f N. Locked, cap 15%%. Type 'cal' first.\n",
             (unsigned)WEEBLE_CONFIG_HASH, P.mass_kg * 1000, P.thrust_max_N);
  lastTickUs = micros();
}

void loop() {
  handleSerial();
  handleWifi();
  uint32_t now = micros();
  if (now - lastTickUs < (uint32_t)(1e6f / cfg::CONTROL_HZ)) return;
  float dt = (now - lastTickUs) * 1e-6f;
  lastTickUs = now;

  static uint32_t tick = 0;
  if ((tick++ % 10) == 0) linkFailsafe();                    // 20 Hz is plenty

  Vec3 g, a;
  if (!mpuRead(g, a)) {
    if (++imuFail > 10 && flight.macro() != Macro::REST) killAll("IMU fail");
    return;
  }
  imuFail = 0;

  Command cmd = flight.update(g, a, dt);
  while (const char* m = flight.popMsg()) { out.print("> "); out.println(m); }

  if (spinOn) {                                              // bench spin test
    if (millis() > spinEndMs || !flight.idleArmed()) { spinOn = false; escUpper.stop(); escLower.stop(); out.println("spin done"); }
    else {
      float rpm = P.max_rpm * sqrtf(spinFrac);
      escUpper.setTargetRPM(rpm); escUpper.update(); escLower.setTargetRPM(rpm); escLower.update();
      if ((teleCount++ % 2) == 0) out.printf("%lu,%.0f,%.0f,%.3f\n", (unsigned long)millis(), escUpper.rpm(), escLower.rpm(), a.z);
    }
    return;
  }
  if (benchServo) return;                                    // servo bench holds its last angle, motors off

  if (flight.outputsLive()) {
    Outputs o = mix(cmd, P);
    srvX.setAngle(o.servo_x_rad); srvY.setAngle(o.servo_y_rad);   // servos stay active (e.g. hold level after landing)
    if (P.use_closed_loop_rpm) {
      escUpper.setTargetRPM(o.rpm_upper); escUpper.update();
      escLower.setTargetRPM(o.rpm_lower); escLower.update();
    } else {
      escUpper.setDirectPulseUs(o.esc_upper_us);
      escLower.setDirectPulseUs(o.esc_lower_us);
    }
  } else {
    safeOutputs();
  }

  if (teleOn && (teleCount++ % (uint32_t)(cfg::CONTROL_HZ / 10)) == 0) {
    const Estimator& e = flight.est;
    out.printf("T %s/%s z=%.2f vz=%.2f x=%.2f y=%.2f tilt=%.1f thr=%.1f\n", macroName(flight.macro()), flight.subStateName(),
               e.pos.z, e.vel.z, e.pos.x, e.pos.y, e.tiltDeg(), e.thrustNow());
  }
}
